    assert not(SRC/'protocol.json').exists() and not(OUT/'preparation.json').exists()
    prior=read(SRC.parent/'h3bf/protocol.json');pre=read(SRC/'preflight.json');seedaudit=read(SRC/'seed-audit.json');assert pre['all_toy_gates_passed'] and not seedaudit['collisions']
    truths=[dict(candidate=r['candidate'],orbits=r['orbits'],source_population=r['source_population'],seeds=[2026600000+64*r['candidate']+bank for bank in range(64)]) for r in prior['truths']]
    sources=[SRC/f'{name}.py' for name in ['common','compiler','firstlex','weights','selector','ledger','ledger_gate','synthetic_gate','firstlex_gate','prepare','preflight','study','gate','freeze']]+[SRC.parent/'h3at/source.py']
