    p=dict(id='H3bq-fresh-eight-positive-three-policy-cost-replication',frozen_utc=now(),truths=truths,normalizers=prior['normalizers'],candidate_prior=prior['candidate_prior'],
        hypotheses=dict(uniform_vs_firstlex='Actual uniform continuation calls U are at least2percent below firstlex F:100U<=98F. Threshold explicitly informed by H3bp2.825688percent reduction; it is a new prospective target, not the previous failed5percent target.',uniform_vs_posterior='Actual uniform continuation calls U are at least5percent below posterior-weighted P:100U<=95P. New comparator, separate scientific decision; not support for5percent versus firstlex.'),
        primary=dict(uniform_vs_firstlex=dict(multiplier=100,comparator_multiplier=98,threshold_percent=2),uniform_vs_posterior=dict(multiplier=100,comparator_multiplier=95,threshold_percent=5),zero_comparator='inconclusive_zero_comparator',joint_or_omnibus_success=False,cost_scope='Actual continuation calls only, summed across every one of1408cases. SharedMAP and policy totals descriptive.'),
        sampling='Same22 previously selected hard-tail truths,64 fresh banks each. Direct numpy.default_rng(2026600000+64*candidateID+bank).choice(M,8,replace=False). This is the same uniform8subset law as H3bm nested uniform16then8, with fresh disjoint RNG seeds; bank overlap remains possible. All1408banks logged before any new targetMAP outcome. Never exclude/redraw anysource,success,failure,tie,duplicate or checkpoint.',
        likelihood='All1541 candidate models retained if compatible with the eight distinct positives. Correct source score C(55,k)*C(M,8), including candidates with8<=M<16; M<8incompatible. Same class prior P(k)=1/3 uniform within k for MAP and posterior trees.',
        policy='Same frozen byte-identical H3bm selector chooses up to4sharedMAP queries, lowestscore/smallestcandidateID guide and lexboardtie. Completeall sharedcheckpoints before compiling. Firstlex uses byte-identicalH3bm feasibilitycompiler. Posterior/uniform use byte-identicalH3bl exactoptimizer with integer reciprocal-score weights/all1weights, depth4 andlex optimal ties. Same full73712N13 query universe. Compileall checkpointsets andeverypolicy beforeany continuationoracle. Compiler sees candidates/catalog/weights/depth only, not case or trueidentity.',
        caching='Reuse only identical immutable compilation inputs: policy,candidates,weights,depth,catalogSHA,predictionsSHA,compilerSHA. Persist canonical input hashes perpolicy. Candidate-tuple grouping is within this one fixed predictions/score/depth run; each group has explicit full policy input identity.',
        correctness='Everycase terminal exact flag must agree across all3policies. This is a correctness invariant from common feasible depth4class, not scientific success. Prior successes use0continuation. Exact firstlex-infeasible certificates apply to all3policies and remain unresolved at0continuation; >16models have a binary information bound. If firstlex-feasible but optimized missing/capped/infeasible, whole-study incomplete. No fallback, pruning, partial claims or extendeddepth.',
        execution='One durable ledger, fixed firstlex/posterior/uniform arm order percase. SharedMAP acquired/charged once. Every continuation independently reacquires its oracle answer, even when the board was asked in anotherarm; annotate all earlier samecasequerysequences. No cache/free answer reuse. No imported archivedstudy answer use. Every query fsynced before separate oracle read and immediatehashlinked answer.',
        supervision='11264positive source appearances shared across3policies;33792arm appearances, not33792newexamples. Actualpaidcalls=sharedMAP+F+P+U<=22528. Eachpolicycost=sharedMAP+owncontinuation<=11264. Reportpositivecounts, globallydistinctsourceboards, samecasequeryreacquisitions anduniquequeryboards separately.',
        duplicates='Retain and report unordered identical8banks withinstudy and against allH3bm eight-positivebanks; no exclusion. Seed audit checks explicit integer seed fields from prior Loki protocols and does not claim undocumented streams are audited.',
        gates='Prefreeze source-law boundary/count fixtures, directdraw toy, weightedandfirstlex brute-force/depth/lex/cap fixtures,5001digitserialization andseedregistry. Runtime repeats compilerfixtures withstates/splits globallycharged, freshall1541graphfilter/scoreparity and8archivedquery ledgerdurabilityfixtures before newbanks. Prefreeze CPUtiming separate from monitoredexperiment.',
        ledger=prior['ledger'],ledger_gate=prior['ledger_gate'],
        budget=dict(aggregate_CPU_seconds=600,wall_seconds=900,GPUs=0,max_memo_states_total=2000000,max_canonical_split_attempts_total=50000000,max_integer_bits=100000,membership_calls=22528,shared_MAP_calls=5632,continuation_calls_per_policy=5632,source_positive_union_appearances=11264,positive_arm_appearances=33792,planned_cases=1408,enforcement='Aggregate caps across all3policies, scientificgates, preparation, serialization andmonitor. Cap/error means whole-study incomplete with all1408plannedstatuses retained. Prefreeze gates and postrun independent audit separately timed.'),
        interpretation='Fresh finite selected-truth source-bank replication only. Two separately reported endpointdecisions, no omnibusorpopulation inference. Selected22truths remain previouslyexamined; no newarbitraryrules or independenttruthgeneralization. Completecandidatepredictions/noiselessbinarymembership are stronger supervision than positive-onlylearning. BPAdamW notmeasured.',
        source_sha256={str(path.relative_to(ROOT)):sha(path) for path in sources},source_data_sha256={rel:sha(ROOT/rel) for rel in sorted(set(inputs))},target_data_sha256={})
    assert sha(SRC/'firstlex.py')==sha(SRC.parent/'h3bm/compiler.py') and sha(SRC/'compiler.py')==sha(SRC.parent/'h3bl/compiler.py') and sha(SRC/'weights.py')==sha(SRC.parent/'h3bl/weights.py')
    for name in ['selector.py','ledger.py']:assert sha(SRC/name)==sha(SRC.parent/'h3bm'/name)
    save(SRC/'protocol.json',p);print('FROZEN',sha(SRC/'protocol.json'),flush=True)


